-- Artificial journals verified by Rust before bundling.
SET ROLE nqc_miner_import_owner;
CREATE TABLE nqc_miner_v1.test_inputs(name text PRIMARY KEY, payload jsonb NOT NULL);
UPDATE nqc_miner_v1.import_identity SET database_id='dfb1a49f-38d1-40ab-b19d-90a9577271be'::uuid;
GRANT USAGE ON SCHEMA nqc_miner_v1 TO nqc_miner_import_writer,nqc_miner_import_outsider;
GRANT SELECT ON nqc_miner_v1.test_inputs,nqc_miner_v1.import_identity TO nqc_miner_import_writer;
GRANT SELECT,INSERT ON nqc_miner_v1.runs,nqc_miner_v1.journal_ledger,nqc_miner_v1.outbox,nqc_miner_v1.import_quarantine TO nqc_miner_import_writer;
GRANT EXECUTE ON FUNCTION nqc_miner_v1.import_verified_journal(jsonb) TO nqc_miner_import_writer;
